sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    // Login buttons
    c.loginStudent = function() {
        $window.location.href = "?id=campus_student_login";
    };

    c.loginOrganizer = function() {
        $window.location.href = "?id=campus_organizer_login";
    };

    // Signup buttons
    c.signupStudent = function() {
        $window.location.href = "?id=campus_student_signup";
    };

    c.signupOrganizer = function() {
        $window.location.href = "?id=campus_organizer_signup";
    };

};

sp_widget.css:
/* =========================================================
   CAMPUS CONNECT
   FULL PAGE UI POLISH
   ========================================================= */


/* =========================================================
   SERVICE PORTAL CONTAINER FIX
   ========================================================= */

.campus-home {
    position: relative;

    width: 100vw;
    max-width: none;

    min-height: 100vh;

    margin-left: calc(50% - 50vw);
    margin-right: calc(50% - 50vw);

    margin-top: -1px;

    overflow: hidden;

    background: #071a2f;

    box-sizing: border-box;
}


/* Make every child use border-box */

.campus-home *,
.campus-home *::before,
.campus-home *::after {
    box-sizing: border-box;
}


/* =========================================================
   REAL UNIVERSITY CAMPUS BACKGROUND
   ========================================================= */

.cc-campus-bg {
    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    /*
     * IMPORTANT:
     * Upload your university image into ServiceNow first.
     *
     * Then replace the URL below with the ServiceNow
     * image URL.
     */

    background-image: url("https://images.shiksha.com/mediadata/images/1542782054php9173Sy_g.jpg");

    background-size: cover;

    /*
     * Slightly shift the image so the university building
     * and students remain visible behind the UI.
     */

    background-position: center center;

    background-repeat: no-repeat;

    /*
     * Slight zoom prevents empty edges during animation.
     */

    transform: scale(1.04);

    /*
     * Slow cinematic movement.
     */

    animation:
        ccCampusImageMotion
        24s
        ease-in-out
        infinite
        alternate;

    transform-origin: center center;

    will-change: transform, background-position;

    z-index: 0;
}


/* =========================================================
   UNIVERSITY IMAGE MOTION
   ========================================================= */

@keyframes ccCampusImageMotion {

    0% {

        transform: scale(1.04);

        background-position:
            50% 50%;

    }

    50% {

        transform: scale(1.065);

        background-position:
            52% 48%;

    }

    100% {

        transform: scale(1.09);

        background-position:
            48% 52%;

    }

}


/* =========================================================
   DARK BACKGROUND OVERLAY
   ========================================================= */
.cc-bg-overlay {
    position: absolute;

    inset: 0;

    width: 100%;
    height: 100%;

    background:
        linear-gradient(
            90deg,
            rgba(3, 18, 38, 0.96) 0%,
            rgba(4, 27, 52, 0.88) 34%,
            rgba(4, 25, 48, 0.68) 60%,
            rgba(4, 19, 36, 0.78) 100%
        );

    z-index: 1;

    pointer-events: none;
}


/* =========================================================
   FLOATING LIGHTS
   ========================================================= */

.cc-floating-light {
    position: absolute;

    width: 260px;
    height: 260px;

    border-radius: 50%;

    filter: blur(80px);

    opacity: 0.16;

    pointer-events: none;

    z-index: 2;
}


.cc-light-one {
    top: 5%;
    left: 20%;

    background: #2388ff;

    animation:
        ccFloatOne
        8s
        ease-in-out
        infinite;
}


.cc-light-two {
    top: 25%;
    right: 12%;

    background: #5caeff;

    animation:
        ccFloatTwo
        10s
        ease-in-out
        infinite;
}


.cc-light-three {
    bottom: 8%;
    left: 48%;

    background: #1477df;

    animation:
        ccFloatThree
        12s
        ease-in-out
        infinite;
}


@keyframes ccFloatOne {

    0%,
    100% {

        transform:
            translate3d(0, 0, 0);

    }

    50% {

        transform:
            translate3d(25px, -20px, 0);

    }

}


@keyframes ccFloatTwo {

    0%,
    100% {

        transform:
            translate3d(0, 0, 0);

    }

    50% {

        transform:
            translate3d(-25px, 20px, 0);

    }

}


@keyframes ccFloatThree {

    0%,
    100% {

        transform:
            translate3d(0, 0, 0);

    }

    50% {

        transform:
            translate3d(20px, -15px, 0);

    }

}


/* =========================================================
   HERO
   ========================================================= */

.cc-hero {
    position: relative;

    width: 100%;

    min-height:
        calc(100vh - 105px);

    display: flex;

    align-items: center;

    padding:
        70px
        6vw
        65px;

    z-index: 3;
}


/* =========================================================
   HERO INNER
   ========================================================= */

.cc-hero-inner {
    width: 100%;

    max-width: 1450px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(0, 1fr)
        minmax(430px, 530px);

    gap:
        clamp(50px, 7vw, 110px);

    align-items: center;
}


/* =========================================================
   LEFT HERO CONTENT
   ========================================================= */

.hero-content {
    max-width: 720px;

    color: #ffffff;
}


/* =========================================================
   TOP LINE
   ========================================================= */

.hero-topline {
    display: inline-flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 18px;

    color: #8fcaff;

    font-size: 13px;

    font-weight: 700;

    letter-spacing: 2px;

    text-transform: uppercase;
}


.hero-dot {
    width: 9px;
    height: 9px;

    border-radius: 50%;

    background: #4ab4ff;

    box-shadow:
        0 0 0 5px rgba(74, 180, 255, 0.12),
        0 0 18px rgba(74, 180, 255, 0.75);
}


/* =========================================================
   HERO BADGE
   ========================================================= */

.hero-badge {
    display: inline-flex;

    align-items: center;

    padding: 11px 18px;

    margin-bottom: 24px;

    border:
        1px solid
        rgba(135, 198, 255, 0.28);

    border-radius: 30px;

    background:
        rgba(37, 88, 135, 0.30);

    color: #dceeff;

    font-size: 14px;

    font-weight: 600;

    backdrop-filter: blur(8px);

    box-shadow:
        0 8px 30px rgba(0, 0, 0, 0.12);
}


/* =========================================================
   HERO TITLE
   ========================================================= */

.hero-content h1 {
    margin: 0;

    font-size:
        clamp(64px, 7vw, 108px);

    line-height: 0.92;

    letter-spacing: -4px;

    font-weight: 800;

    color: #ffffff;

    text-shadow:
        0 10px 35px
        rgba(0, 0, 0, 0.30);
}


.hero-content h1 span {
    display: block;

    color: #cfe8ff;

    background:
        linear-gradient(
            120deg,
            #ffffff 0%,
            #bfe1ff 45%,
            #65b7ff 100%
        );

    -webkit-background-clip: text;
    background-clip: text;

    -webkit-text-fill-color: transparent;
}


/* =========================================================
   DIVIDER
   ========================================================= */

.hero-divider {
    width: 80px;

    height: 4px;

    margin:
        30px 0 25px;

    border-radius: 10px;

    background:
        linear-gradient(
            90deg,
            #54b8ff,
            #1984e8
        );

    box-shadow:
        0 0 18px
        rgba(65, 172, 255, 0.40);
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.hero-description {
    max-width: 650px;

    margin:
        0 0 30px;

    color:
        rgba(235, 245, 255, 0.84);

    font-size: 18px;

    line-height: 1.75;

    font-weight: 400;
}


/* =========================================================
   FEATURE PILLS
   ========================================================= */

.hero-features {
    display: flex;

    flex-wrap: wrap;

    gap: 10px;
}


.hero-feature {
    display: inline-flex;

    align-items: center;

    gap: 9px;

    padding:
        11px 15px;

    border:
        1px solid
        rgba(159, 207, 248, 0.24);

    border-radius: 9px;

    background:
        rgba(21, 55, 84, 0.46);

    color: #dceeff;

    font-size: 14px;

    font-weight: 600;

    backdrop-filter: blur(8px);

    transition:
        transform 0.25s ease,
        background 0.25s ease,
        border-color 0.25s ease;
}


.hero-feature:hover {
    transform:
        translateY(-3px);

    background:
        rgba(32, 83, 125, 0.65);

    border-color:
        rgba(112, 190, 255, 0.48);
}


.feature-icon {
    color: #64c1ff;

    font-weight: 800;
}


/* =========================================================
   ACCESS CARD
   ========================================================= */

.cc-access-card {
    width: 100%;

    padding:
        34px 34px 28px;

    border:
        1px solid
        rgba(255, 255, 255, 0.72);

    border-radius: 25px;

    background:
        linear-gradient(
            145deg,
            rgba(255, 255, 255, 0.97),
            rgba(246, 250, 254, 0.94)
        );

    box-shadow:
        0 35px 80px
        rgba(0, 0, 0, 0.30),

        0 10px 30px
        rgba(0, 0, 0, 0.14);

    backdrop-filter: blur(18px);

    color: #132238;

    position: relative;
}


.cc-access-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: 0;
    right: 0;

    height: 4px;

    border-radius:
        25px 25px 0 0;

    background:
        linear-gradient(
            90deg,
            #1477df,
            #49b1ff
        );
}


/* =========================================================
   ACCESS HEADER
   ========================================================= */

.access-header {
    display: flex;

    align-items: center;

    gap: 16px;

    margin-bottom: 27px;
}


.access-icon {
    width: 54px;
    height: 54px;

    flex:
        0 0 54px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 15px;

    background:
        linear-gradient(
            145deg,
            #0f7bea,
            #218ddd
        );

    font-size: 25px;

    box-shadow:
        0 12px 25px
        rgba(16, 118, 226, 0.25);
}


.access-eyebrow {
    margin-bottom: 2px;

    color: #0c68c9;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 2px;
}


.access-header h2 {
    margin: 0;

    color: #18253a;

    font-size: 30px;

    line-height: 1.15;

    font-weight: 800;
}


.access-header p {
    margin:
        5px 0 0;

    color: #718096;

    font-size: 13px;
}


/* =========================================================
   ACCESS SECTION
   ========================================================= */

.access-section {
    margin-bottom: 25px;
}


.access-section-title {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 12px;

    color: #7a8798;

    font-size: 12px;
}


.access-section-title strong {
    color: #20344d;

    font-size: 13px;
}


/* =========================================================
   LOGIN BUTTONS
   ========================================================= */

.access-buttons {
    display: flex;

    flex-direction: column;

    gap: 10px;
}


.access-btn {
    width: 100%;

    min-height: 66px;

    display: flex;

    align-items: center;

    gap: 13px;

    padding:
        10px 14px;

    border-radius: 12px;

    cursor: pointer;

    text-align: left;

    font-family: inherit;

    transition:
        transform 0.22s ease,
        box-shadow 0.22s ease,
        background 0.22s ease,
        border-color 0.22s ease;
}


.access-btn:hover {
    transform:
        translateY(-2px);
}


.access-student {
    border:
        1px solid
        #2585df;

    background:
        linear-gradient(
            135deg,
            #1478dc,
            #2987df
        );

    color: #ffffff;

    box-shadow:
        0 12px 24px
        rgba(20, 120, 220, 0.23);
}


.access-student:hover {
    box-shadow:
        0 16px 30px
        rgba(20, 120, 220, 0.32);
}


.access-organizer {
    border:
        1px solid
        #d9e2ed;

    background: #ffffff;

    color: #18283c;
}


.access-organizer:hover {
    border-color:
        #a8c8e7;

    background: #f8fbff;

    box-shadow:
        0 10px 24px
        rgba(30, 70, 110, 0.10);
}


.access-btn-icon {
    width: 40px;
    height: 40px;

    flex:
        0 0 40px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background:
        rgba(255, 255, 255, 0.17);

    font-size: 20px;
}


.access-organizer .access-btn-icon {
    background: #edf5ff;
}


.access-btn-content {
    display: flex;

    flex-direction: column;

    gap: 3px;

    flex: 1;
}


.access-btn-content strong {
    font-size: 14px;

    font-weight: 750;
}


.access-btn-content small {
    font-size: 11px;

    line-height: 1.3;

    opacity: 0.75;
}


.access-arrow {
    font-size: 22px;

    line-height: 1;

    opacity: 0.9;
}


/* =========================================================
   DIVIDER
   ========================================================= */

.access-divider {
    display: flex;

    align-items: center;

    gap: 12px;

    margin:
        21px 0;
}


.access-divider::before,
.access-divider::after {
    content: "";

    height: 1px;

    flex: 1;

    background: #dfe6ee;
}


.access-divider span {
    white-space: nowrap;

    color: #98a5b5;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.6px;
}


/* =========================================================
   SIGNUP
   ========================================================= */

.signup-area {
    text-align: center;
}


.signup-heading {
    color: #24364e;

    font-size: 16px;

    font-weight: 750;
}


.signup-area p {
    margin:
        5px 0 14px;

    color: #8290a1;

    font-size: 11px;
}


.signup-buttons {
    display: grid;

    grid-template-columns:
        1fr 1fr;

    gap: 10px;
}


.signup-btn {
    min-height: 46px;

    display: flex;

    align-items: center;
    justify-content: center;

    gap: 8px;

    border:
        1px solid
        #d8e3ef;

    border-radius: 10px;

    background: #ffffff;

    color: #30445d;

    cursor: pointer;

    font-family: inherit;

    font-size: 12px;

    font-weight: 700;

    transition:
        transform 0.22s ease,
        border-color 0.22s ease,
        background 0.22s ease,
        box-shadow 0.22s ease;
}


.signup-btn:hover {
    transform:
        translateY(-2px);

    border-color:
        #9cc8ee;

    background: #f7fbff;

    box-shadow:
        0 8px 20px
        rgba(30, 90, 145, 0.10);
}


.signup-student {
    color: #0969c5;
}


/* =========================================================
   TRUST MESSAGE
   ========================================================= */

.access-trust {
    display: flex;

    align-items: center;
    justify-content: center;

    gap: 8px;

    margin-top: 21px;

    padding-top: 17px;

    border-top:
        1px solid
        #e4e9ef;

    color: #8290a1;

    font-size: 10px;

    text-align: center;
}


.trust-check {
    color: #20a565;

    font-size: 14px;

    font-weight: 800;
}


/* =========================================================
   BOTTOM STRIP
   ========================================================= */

.cc-bottom-strip {
    position: relative;

    z-index: 4;

    width: 100%;

    min-height: 54px;

    display: flex;

    align-items: center;
    justify-content: center;

    gap: 30px;

    padding:
        12px 30px;

    background:
        rgba(4, 22, 42, 0.96);

    border-top:
        1px solid
        rgba(135, 194, 240, 0.15);

    border-bottom:
        1px solid
        rgba(135, 194, 240, 0.10);

    backdrop-filter: blur(12px);
}


.bottom-item {
    display: flex;

    align-items: center;

    gap: 9px;

    color: #bdd9ef;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1.1px;

    white-space: nowrap;
}


.bottom-icon {
    color: #54baff;

    font-size: 13px;
}


.bottom-line {
    width: 1px;

    height: 20px;

    background:
        rgba(164, 205, 239, 0.24);
}


/* =========================================================
   FOOTER
   ========================================================= */

.cc-footer {
    position: relative;

    z-index: 4;

    min-height: 58px;

    width: 100%;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding:
        16px 6vw;

    background: #041426;

    color: #7890a8;

    font-size: 11px;
}


.cc-footer strong {
    color: #d8ebfb;

    font-weight: 750;
}


.footer-separator {
    margin:
        0 7px;

    color: #46647d;
}


.footer-right {
    text-align: right;

    color: #607b94;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1050px) {

    .cc-hero {

        padding:
            55px
            5vw
            50px;

    }


    .cc-hero-inner {

        grid-template-columns:
            minmax(0, 1fr)
            minmax(380px, 470px);

        gap: 45px;

    }


    .hero-content h1 {

        font-size:
            clamp(58px, 8vw, 85px);

    }


    .hero-description {

        font-size: 16px;

    }


    .cc-access-card {

        padding:
            30px 27px 25px;

    }

}


/* =========================================================
   MOBILE / SMALL TABLET
   ========================================================= */

@media (max-width: 850px) {

    .cc-hero {

        min-height: auto;

        padding:
            55px
            24px
            45px;

    }


    .cc-hero-inner {

        grid-template-columns: 1fr;

        max-width: 650px;

        gap: 45px;

    }


    .hero-content {

        max-width: 650px;

        text-align: center;

    }


    .hero-topline {

        justify-content: center;

    }


    .hero-badge {

        margin-left: auto;
        margin-right: auto;

    }


    .hero-content h1 {

        font-size:
            clamp(58px, 13vw, 82px);

        letter-spacing: -3px;

    }


    .hero-divider {

        margin-left: auto;
        margin-right: auto;

    }


    .hero-description {

        margin-left: auto;
        margin-right: auto;

    }


    .hero-features {

        justify-content: center;

    }


    .cc-access-card {

        max-width: 520px;

        margin: 0 auto;

    }


    .cc-bottom-strip {

        flex-wrap: wrap;

        gap:
            15px 20px;

    }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 560px) {

    .campus-home {

        width: 100vw;

        margin-left:
            calc(50% - 50vw);

        margin-right:
            calc(50% - 50vw);

    }


    .cc-hero {

        padding:
            40px
            16px
            35px;

    }


    .hero-topline {

        font-size: 10px;

        letter-spacing: 1.4px;

    }


    .hero-badge {

        padding:
            9px 13px;

        font-size: 11px;

    }


    .hero-content h1 {

        font-size: 52px;

        letter-spacing: -2px;

    }


    .hero-description {

        font-size: 14px;

        line-height: 1.65;

    }


    .hero-features {

        flex-direction: column;

        align-items: stretch;

    }


    .hero-feature {

        justify-content: center;

    }


    .cc-access-card {

        padding:
            27px
            20px
            22px;

        border-radius: 20px;

    }


    .access-header h2 {

        font-size: 26px;

    }


    .access-btn {

        min-height: 62px;

    }


    .signup-buttons {

        grid-template-columns: 1fr;

    }


    .cc-bottom-strip {

        flex-direction: column;

        gap: 10px;

        padding:
            17px 15px;

    }


    .bottom-line {

        display: none;

    }


    .cc-footer {

        flex-direction: column;

        justify-content: center;

        text-align: center;

        padding:
            18px
            15px;

        line-height: 1.6;

    }


    .footer-right {

        text-align: center;

    }

}


/* =========================================================
   VERY SMALL DEVICES
   ========================================================= */

@media (max-width: 380px) {

    .hero-content h1 {

        font-size: 45px;

    }


    .cc-access-card {

        padding:
            23px
            16px
            20px;

    }


    .access-header {

        gap: 11px;

    }


    .access-icon {

        width: 47px;
        height: 47px;

        flex-basis: 47px;

        font-size: 21px;

    }


    .access-header h2 {

        font-size: 23px;

    }

}


/* =========================================================
   REDUCED MOTION ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    .cc-campus-bg,
    .cc-floating-light {

        animation: none !important;

    }

}
/* =========================================
   HIDE DECORATIVE BLUE CIRCLES
   Keep university background image unchanged
   ========================================= */

.cc-floating-light {
    display: none !important;
}

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */

})();(function() {

    data.platform_name = "Campus Connect";

    data.student_login_message =
        "Student Login";

    data.organizer_login_message =
        "Organizer Login";

    data.student_signup_message =
        "Student Sign Up";

    data.organizer_signup_message =
        "Organizer Sign Up";

})();
